package cn.mop.adapters.email;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.mail.*;
import jakarta.mail.internet.MimeMessage;
import org.eclipse.angus.mail.smtp.SMTPSendFailedException;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Isolated protocol/input tests only. They are not real mail delivery evidence. */
class SmtpMailClientTest {
    static final String SENDER="sender@example.test",RECIPIENT="recipient@example.test",ID="55000000-0000-4000-8000-000000000001";
    final SmtpSettings settings=new SmtpSettings("smtp.example.test",SENDER,"synthetic-secret",SENDER,"MOP 测试",RECIPIENT,Set.of(RECIPIENT));
    Session mockSession(){var session=mock(Session.class);when(session.getProperties()).thenReturn(new Properties());return session;}
    @Test void rejectsHeaderInjectionDisplayNamesAndMultipleAddresses(){for(String value:List.of("a@example.test\r\nBcc:other@example.test","Name <a@example.test>","a@example.test,b@example.test","a@localhost","a..b@example.test","a@example.test;other@example.test"))assertThrows(IllegalArgumentException.class,()->SmtpSettings.address(value));assertEquals("test@example.test",SmtpSettings.address("Test@Example.Test"));assertFalse(settings.toString().contains("synthetic-secret"));}
    @Test void permitsOnlyConfiguredRecipientsAndAuthenticatedSender(){assertFalse(settings.allows("other@example.test"));assertThrows(IllegalArgumentException.class,()->new SmtpSettings("smtp.example.test",SENDER,"secret",RECIPIENT,"MOP",RECIPIENT,Set.of(RECIPIENT)));}
    @Test void requiresTlsHostnameChecksTimeoutsAndNoDebug(){var p=new SmtpMailClient(settings).properties();assertEquals("true",p.getProperty("mail.smtps.ssl.checkserveridentity"));assertEquals("true",p.getProperty("mail.smtps.ssl.enable"));assertEquals("10000",p.getProperty("mail.smtps.timeout"));assertEquals("false",p.getProperty("mail.debug.auth"));assertFalse(p.containsKey("mail.smtps.ssl.trust"));}
    @Test void createsUtf8SingleRecipientPlainTextAndStableMessageId()throws Exception{var client=new SmtpMailClient(settings);MimeMessage message=client.message(Session.getInstance(new Properties()),ID,RECIPIENT,"测试主题","明确测试正文");assertEquals(1,message.getAllRecipients().length);assertEquals("测试主题",message.getSubject());assertEquals("明确测试正文",message.getContent());assertEquals("<mop."+ID+"@example.test>",message.getMessageID());assertTrue(message.getContentType().toLowerCase().startsWith("text/plain"));assertNull(message.getRecipients(Message.RecipientType.BCC));}
    @Test void authenticationProbeNeverSubmitsMail()throws Exception{var session=mockSession();var transport=mock(Transport.class);when(session.getTransport("smtps")).thenReturn(transport);new SmtpMailClient(settings,()->session).check();verify(transport).connect("smtp.example.test",465,SENDER,"synthetic-secret");verify(transport,never()).sendMessage(any(),any());verify(transport).close();}
    @Test void rejectedAuthenticationIsSafeAndNeverSubmitsMail()throws Exception{var session=mockSession();var transport=mock(Transport.class);when(session.getTransport("smtps")).thenReturn(transport);doThrow(new AuthenticationFailedException("synthetic-secret must not be returned")).when(transport).connect(anyString(),anyInt(),anyString(),anyString());var failure=assertThrows(SmtpMailClient.Failure.class,()->new SmtpMailClient(settings,()->session).send(ID,RECIPIENT,"Test","Test"));assertEquals("EMAIL_AUTHENTICATION_REJECTED",failure.category);assertFalse(failure.outcomeUnknown);assertNull(failure.getCause());assertFalse(failure.toString().contains("synthetic-secret"));verify(transport,never()).sendMessage(any(),any());}
    @Test void responseLossDuringSubmissionIsUnknownAndNotRetried()throws Exception{var session=mockSession();var transport=mock(Transport.class);when(session.getTransport("smtps")).thenReturn(transport);doThrow(new MessagingException("raw provider detail")).when(transport).sendMessage(any(),any());var failure=assertThrows(SmtpMailClient.Failure.class,()->new SmtpMailClient(settings,()->session).send(ID,RECIPIENT,"Test","Test"));assertTrue(failure.outcomeUnknown);assertEquals("EMAIL_SUBMISSION_OUTCOME_UNKNOWN",failure.category);verify(transport,times(1)).sendMessage(any(),any());}
    @Test void explicitSmtpRejectionIsFailedAndNotUnknown()throws Exception{var session=mockSession();var transport=mock(Transport.class);when(session.getTransport("smtps")).thenReturn(transport);doThrow(new SMTPSendFailedException("DATA",550,"raw provider detail",null,null,null,null)).when(transport).sendMessage(any(),any());var failure=assertThrows(SmtpMailClient.Failure.class,()->new SmtpMailClient(settings,()->session).send(ID,RECIPIENT,"Test","Test"));assertFalse(failure.outcomeUnknown);assertEquals(550,failure.smtpCode);}
    @Test void unauthorizedRecipientAndSubjectInjectionFailBeforeNetwork(){var session=mock(Session.class);var client=new SmtpMailClient(settings,()->session);assertThrows(SmtpMailClient.Failure.class,()->client.send(ID,"other@example.test","Test","Test"));assertThrows(SmtpMailClient.Failure.class,()->client.send(ID,RECIPIENT,"Test\r\nBcc:other","Test"));verifyNoInteractions(session);}
    @Test void loadsOnlyPrivateFileOrEnvironmentSecretAndRejectsPlaintextConfig(@TempDir Path dir)throws Exception{var path=dir.resolve("config.json");String base="{\"host\":\"smtp.example.test\",\"port\":465,\"username\":\"sender@example.test\",\"sender\":\"sender@example.test\",\"sender_name\":\"MOP\",\"test_recipient\":\"recipient@example.test\",\"allowed_recipients\":[\"recipient@example.test\"]}";Files.writeString(path,base);assertEquals(SENDER,SmtpSettings.load(path,new ObjectMapper(),"synthetic-secret").sender());assertThrows(IllegalArgumentException.class,()->SmtpSettings.load(path,new ObjectMapper(),null));Files.writeString(path,base.replace("465","25"));assertThrows(IllegalArgumentException.class,()->SmtpSettings.load(path,new ObjectMapper(),"synthetic-secret"));Files.writeString(path,base.replace("\"port\":465","\"port\":465,\"password\":\"must-not-be-accepted\""));assertThrows(IllegalArgumentException.class,()->SmtpSettings.load(path,new ObjectMapper(),"synthetic-secret"));}
}
